"The saucer skims the sea toward the sun. Jump the big waves, keep off the rocks, grab the lights.":"飞碟掠过海面飞向太阳。跳过大浪，避开岩石，抓住光点。",
"WIPEOUT":"撞毁了",
"THE SONG":"歌曲",
"THE JOURNEY":"旅程",
"From the Earth in your hands to Planet Javeda, in the little orange ship. Every planet on the way is under a meteor shower.":"乘着橙色小飞船，从你手中的地球飞往Javeda星球。沿途的每颗星球都笼罩在流星雨之下。",
"The long way home: the meteors hunt you in flight too, and you start with # hearts.":"漫长的回家路：飞行中流星也会追击你，开局只有#颗爱心。",
"PETAL RAIN":"花瓣雨",
"The rose in the canyon is losing its petals. Catch them in the saucer's green beam before they hit the cracked ground.":"峡谷里的玫瑰正在凋落。在花瓣落到裂开的地面之前，用飞碟的绿色光束接住它们。",
"ROSE # / #":"玫瑰 # / #",
"THE ROSE LOST ALL ITS PETALS":"玫瑰的花瓣掉光了",
"Climb the giant stem all the way to the bloom - round the thorns, through the dew.":"沿着巨大的花茎一路爬到花朵 - 绕过尖刺，穿过露珠。",
"THROUGH THE GAP":"穿过缝隙",
"# M · # IN A ROW":"#米 · #连击",
