"YOUR SHADOW GOT YOU":"你被影子抓住了",
"THE KING OF FORGETTING":"遗忘之王",
"LAZY JO × ZIRKA · LEVEL #":"LAZY JO × ZIRKA · 关卡#",
"NIGHT FLIGHT":"夜间飞行",
"District #, the night the monsters of forgetting came. Fly Jo's saucer between the neon towers and light them up.":"第#区，遗忘怪兽来袭的那一夜。驾驶Jo的飞碟穿梭在霓虹高楼之间，把它们点亮。",
"# DOWN":"击落#",
"STORM #s":"风暴 #秒",
"THE SWARM!":"怪群来了！",
"LAZY JO × ZIRKA · LEVEL # PART #":"LAZY JO × ZIRKA · 关卡# 第#部分",
"Zirka's bike over the rooftops of District # - jump the gaps on the beat, and Zirka's gun takes care of what dives in.":"Zirka骑着摩托飞越第#区的屋顶 - 踩准节拍跳过缺口，俯冲过来的敌人交给Zirka的枪。",
"# BOLTS · # DOWN":"闪电# · 击落#",
"x# · # BOLTS · # DOWN":"x# · 闪电# · 击落#",
"The King of Forgetting hangs over the city. Bring him down before the song ends. Gadgets float up for Jo - and the wolf token hands the fight to Zirka on the roof below.":"遗忘之王悬在城市上空。在歌曲结束前把他打下来。道具会为Jo飘上来 - 狼徽章会把战斗交给下方屋顶上的Zirka。",
"x# · # CORE HITS":"x# · 核心命中#",
"# CORE HITS":"核心命中#",
"Jo's orange saucer drops into the city from the sky. Freefall down between the towers - through the skybridges, past the cranes and the helicopters - all the way to the streets.":"Jo的橙色飞碟从天而降，冲进城市。在高楼之间自由落体 - 穿过空中走廊，避开吊车和直升机，一路落到街道上。",
"# M DOWN":"下降#米",
"A CRANE!":"吊车！",
"A night race through the city, towards the moon, in Jo's silver car - its tail lights drawing a trail of light behind it. Seven cars start ahead of you: drift round the corners, hit the nitro on the beat and be first to the river.":"开着Jo的银色跑车，在夜色中穿城飞驰，奔向月亮 - 尾灯在身后拖出一道光轨。七辆车在你前面出发：弯道漂移，踩准节拍开氮气，第一个冲到河边。",
"P# · # KM/H":"第#名 · #km/h",
"Across the hologram clockwork on the stage. Jo's saucer hooks its beam onto the pendulums - swing, let go, fly, hook the next one. Make it all the way before the song runs out.":"穿越舞台上的全息钟表机关。Jo的飞碟用光束勾住钟摆 - 摆荡、放开、飞出、勾住下一个。在歌曲结束前到达终点。",
"# M · # ON THE BEAT":"#米 · 踩准节拍#次",
"YOU FELL":"你掉下去了",
"The room from the cover, from above. Jo's saucer never stops - it draws a trail of light on the rug wherever it goes. Make it the longest light in the room.":"从上方俯瞰封面里的房间。Jo的飞碟永不停下 - 它走到哪里，就在地毯上画出一道光轨。让它成为房间里最长的光。",
"TRAIL # M":"光轨 #米",
"CROSSED!":"撞线了！",
"Inside the neon cup from the cover. The saucer is the paddle, a purple drop is the ball - smash the ice cubes and the pink splash before the ice comes down to you.":"在封面里的霓虹杯子中。飞碟是球拍，紫色水滴是球 - 在冰块压下来之前，砸碎冰块和粉色水花。",
"# BROKEN · # LEFT":"已击碎# · 剩余#",
"# BROKEN · # LEFT · # IN A ROW":"已击碎# · 剩余# · #连击",
"THE ICE COMES DOWN":"冰块压下来了",
"MISSED IT":"没接住",
"The old houses on the street from the cover, at dusk, in the fog. Ghosts come up in the windows on the beat - catch them with the saucer's beam before they duck away.":"封面里那条街上的老房子，黄昏，雾中。幽灵会随着节拍出现在窗口 - 在它们躲起来之前用飞碟的光束抓住。",
"# CAUGHT · HAUNTED #/#":"抓到# · 闹鬼 #/#",
"HAUNTED":"闹鬼了",
"LAZY JO FEAT. ZIRKA · LEVEL #":"LAZY JO FEAT. ZIRKA · 关卡#",
"A purple and gold court floating in the white sky from the cover, Zirka's saucer up by the hoop. Hold to wind up, let go in the green - on the beat it's a swish.":"封面中漂浮在白色天空里的紫金球场，Zirka的飞碟停在篮筐旁。长按蓄力，在绿色区域松开 - 踩准节拍就是空心入网。",
"Warm up on your own":"自己热身",
"#/# IN · # SWISH":"#/# 命中 · 空心#",
"The blue sky and the islands from the cover. A gold frame stands in the sea; Jo's saucer carries the pieces down in its beam - island chunks, gold, sky, cloud. Fill a row and it bursts gold.":"封面里的蓝天和岛屿。海中立着一个金色框架，Jo的飞碟用光束把方块运下来 - 岛屿碎块、金子、天空、云朵。填满一行，它就会金光四溅。",
"# ROWS":"#行",
"LAZY JO FT ZIRKA · LEVEL #":"LAZY JO FT ZIRKA · 关卡#",
"A car park on the wet street from the cover, at night, in the rain. The blue car is boxed in - slide the others out of its way so it can drive out.":"封面里湿漉漉街道上的停车场，雨夜。蓝色的车被堵住了 - 把其他车滑开，让它开出去。",
