"LAZY JO FT ZIRKA · LEVEL # · PART #":"LAZY JO FT ZIRKA · 关卡# · 第#部分",
"The wet street from the cover at night, in the rain. The saucer's beam goes flat across it - bend it with the mirrors so it reaches the car's headlights.":"封面里湿漉漉的街道，雨夜。飞碟的光束平射过街道 - 用镜子让它转弯，照到车的大灯。",
"STREET # · # LIT · # BARS":"街道# · 点亮# · #小节",
"Jo's studio at night from the cover - the big speakers, the screen with the crowd, the skull on the desk. On the desk the drum machine: # pads lit from under, each its own note, and Jo's saucer hovering over them.":"封面里夜晚的Jo的工作室 - 大音箱、显示观众的屏幕、桌上的骷髅头。桌上是鼓机：#个从下方发光的打击垫，每个都是一个音，Jo的飞碟悬在它们上方。",
