"Peace inside.<br>Level # cleared: <b>Hoops ∞</b> is open in the gold Endless list.":"Peace inside.<br>第#关已通关：金色无尽模式列表里的<b>Hoops ∞</b>已解锁。",
"Hold to wind up and let go while the marker is in the green - two bars on the clock. <b>Go again.</b>":"长按蓄力，标记在绿色区域时松手 - 限时两小节。<b>再来一次。</b>",
"Inside the neon cup from the cover. The saucer is the paddle, a purple drop is the ball - smash the ice cubes and the pink splash before the ice comes down to you. <b>Endless:</b> the ice never stops pouring in - faster every # bars, a heart back every #.":"封面上那只霓虹杯子里。飞碟是挡板，紫色水滴是球 - 在冰块压下来之前，砸碎冰块和粉色水花。<b>无尽模式：</b>冰块倒个不停 - 每#小节变快，每#小节回一颗爱心。",
"Score <b>#</b> · # ice cubes · # power shots · # all clear":"分数 <b>#</b> · #块冰 · #次强力击球 · #次全清",
