"The city at sunset from the cover, high over the towers - the sky going from purple to fire, the towers lit. <b>Part # · Rooftop Golf:</b> nine holes on the roofs, every one with something new. <b>Endless:</b> it never stops - harder every # bars, a heart back every #.":"封面上日落时分的城市，高悬在楼群之上 - 天空从紫色烧成火红，楼群灯火通明。<b>第#部分 · Rooftop Golf：</b>屋顶上的九个洞，每一洞都有新花样。<b>无尽模式：</b>永不停止 - 每#小节变难，每#小节回一颗爱心。",
"The city at sunset from the cover, high over the towers - the sky going from purple to fire, the towers lit. <b>Part # · Sky Hockey:</b> air hockey on a roof against the shadow, round after round. <b>Endless:</b> it never stops - harder every # bars, a heart back every #.":"封面上日落时分的城市，高悬在楼群之上 - 天空从紫色烧成火红，楼群灯火通明。<b>第#部分 · Sky Hockey：</b>在屋顶上和影子打桌上冰球，一回合接一回合。<b>无尽模式：</b>永不停止 - 每#小节变难，每#小节回一颗爱心。",
"The night from the cover - the stars, the lasers crossing over the black car with the glowing pink hood and the rider on its roof - and Jo's saucer. <b>Part # · Neon Pinball:</b> a real pinball table on the floor in front of the car. <b>Endless:</b> it never stops - harder every # bars, a heart back every #.":"封面上的夜晚 - 星星，激光交错掠过那辆粉色发光引擎盖的黑色汽车和车顶上的骑手 - 还有Jo的飞碟。<b>第#部分 · Neon Pinball：</b>车前地面上一台真正的弹珠台。<b>无尽模式：</b>永不停止 - 每#小节变难，每#小节回一颗爱心。",
"The night from the cover - the stars, the lasers crossing over the black car with the glowing pink hood and the rider on its roof - and Jo's saucer. <b>Part # · Speaker Push:</b> the dance floor, the speakers off, the pads where they belong. <b>Endless:</b> it never stops - harder every # bars, a heart back every #.":"封面上的夜晚 - 星星，激光交错掠过那辆粉色发光引擎盖的黑色汽车和车顶上的骑手 - 还有Jo的飞碟。<b>第#部分 · Speaker Push：</b>舞池里，音箱没开，发光垫标出它们该去的位置。<b>无尽模式：</b>永不停止 - 每#小节变难，每#小节回一颗爱心。",
"The wet street from the cover at night, in the rain. The saucer's beam goes flat across it - bend it with the mirrors so it reaches the car's headlights. <b>Endless:</b> it never stops - the clock gets shorter every # bars, a heart back every #.":"封面上雨夜里湿漉漉的街道。飞碟的光束平平地横穿过去 - 用镜子把它折过去，照到汽车的车头灯。<b>无尽模式：</b>永不停止 - 每#小节时间变短，每#小节回一颗爱心。",
"A car park on the wet street from the cover, at night, in the rain. The blue car is boxed in - slide the others out of its way so it can drive out. <b>Endless:</b> it never stops - the clock gets shorter every # bars, a heart back every #.":"封面上湿漉漉街道旁的停车场，雨夜。蓝色的车被堵住了 - 把其他车滑开，让它开出去。<b>无尽模式：</b>永不停止 - 每#小节时间变短，每#小节回一颗爱心。",
"The crowd from the cover under the blue light, every hand up, the big white light behind - and nine lights over them, each its own note. Jo's saucer hovers by the one you play. <b>Endless:</b> the pattern never stops - less time every # bars, a heart back every #.":"封面上蓝光下的人群，人人举起双手，身后是巨大的白光 - 头顶有九盏灯，每盏都有自己的音。Jo的飞碟会停在你按的那盏旁边。<b>无尽模式：</b>序列永不停止 - 每#小节时间变少，每#小节回一颗爱心。",
"Across the hologram clockwork on the stage. Jo's saucer hooks its beam onto the pendulums - swing, let go, fly, hook the next one. Make it all the way before the song runs out. <b>Endless:</b> the clockwork never ends - wider every # bars, a heart back every #.":"穿越舞台上的全息发条机关。Jo的飞碟用光束勾住钟摆 - 摆荡、松开、飞出、勾住下一个。在歌曲结束前一路通过。<b>无尽模式：</b>发条机关没有尽头 - 每#小节间距变宽，每#小节回一颗爱心。",
"The room from the cover, from above. Jo's saucer never stops - it draws a trail of light on the rug wherever it goes. Make it the longest light in the room. <b>Endless:</b> it never ends - faster every # bars, a heart back every #.":"俯瞰封面上的房间。Jo的飞碟停不下来 - 它走到哪里，就在地毯上画出一道光迹。让它成为房间里最长的光。<b>无尽模式：</b>永无止境 - 每#小节变快，每#小节回一颗爱心。",
