"Score <b>#</b> · # m · # pendulums · # sparks · # on the beat":"分数 <b>#</b> · #米 · #个钟摆 · #个火花 · 踩准节拍#次",
"<b>#</b> of swinging · # m · # pendulums · # sparks · # on the beat":"摆荡 <b>#</b> · #米 · #个钟摆 · #个火花 · 踩准节拍#次",
