"Lap <b>#</b> · # games · <b>#</b> without stopping · # down · # king fallen":"第<b>#</b>圈 · #个游戏 · 连续坚持<b>#</b> · 击倒#个 · #个国王倒下",
"Lap <b>#</b> · # games · <b>#</b> without stopping · # down · # kings fallen":"第<b>#</b>圈 · #个游戏 · 连续坚持<b>#</b> · 击倒#个 · #个国王倒下",
"Every part's rules in turn, one score, # hearts. Your best goes on the <b>Level # Remix</b> scoreboard.":"轮流使用每个部分的规则，一个总分，#颗爱心。你的最佳成绩会登上<b>第#关混音模式</b>排行榜。",
