"Score <b>#</b> · # · <b>#</b> / # petals":"分数 <b>#</b> · # · 花瓣 <b>#</b> / #",
"Five pieces back where they belong. <b>The heart is whole.</b><br>Part # is harder.":"五块碎片回到了原位。<b>心完整了。</b><br>第#部分更难。",
"Seven pieces back where they belong. <b>The heart is whole.</b><br>Part # is harder.":"七块碎片回到了原位。<b>心完整了。</b><br>第#部分更难。",
"Nine pieces back where they belong. <b>The heart is whole.</b>":"九块碎片回到了原位。<b>心完整了。</b>",
"<b>#</b> of # pieces home · #":"<b>#</b>/#块碎片归位 · #",
"The ghosts were faster. <b>Go again.</b>":"幽灵比你快。<b>再来一次。</b>",
"It's still in pieces. <b>Go again.</b>":"它还是碎的。<b>再来一次。</b>",
"PETALS <b id=\"pn\">#</b>":"花瓣 <b id=\"pn\">#</b>",
"The heart keeps breaking. Mend it, and its pieces scatter again. Every piece has a <b>clock</b>, and each round the ghosts are faster and there are more of them. <b># hearts</b>: a ghost or a late piece takes one, one comes back every # bars.":"心一次又一次地碎裂。修好它，碎片又会再次散落。每块碎片都有<b>倒计时</b>，每一轮幽灵都会更快、更多。<b>#颗爱心</b>：碰到幽灵或碎片超时会扣一颗，每#小节回复一颗。",
"The heart keeps breaking. Mend it, and its pieces scatter again in the thick fog. Every piece has a <b>clock</b>, and each round the ghosts are faster and there are more of them. <b># hearts</b>: a ghost or a late piece takes one, one comes back every # bars.":"心一次又一次地碎裂。修好它，碎片又会在浓雾中再次散落。每块碎片都有<b>倒计时</b>，每一轮幽灵都会更快、更多。<b>#颗爱心</b>：碰到幽灵或碎片超时会扣一颗，每#小节回复一颗。",
"The heart keeps breaking. Mend it, and its pieces scatter again, glowing only on the heartbeat. Every piece has a <b>clock</b>, and each round the ghosts are faster and there are more of them. <b># hearts</b>: a ghost or a late piece takes one, one comes back every # bars.":"心一次又一次地碎裂。修好它，碎片又会再次散落，只在心跳时发光。每块碎片都有<b>倒计时</b>，每一轮幽灵都会更快、更多。<b>#颗爱心</b>：碰到幽灵或碎片超时会扣一颗，每#小节回复一颗。",
"MENDED<small>+# · it breaks again: round #</small>":"修好了<small>+# · 又碎了：第#轮</small>",
"PETAL<small>+#</small>":"花瓣<small>+#</small>",
"A CHILL<small># heart left - back to the last piece</small>":"一阵寒意<small>剩#颗爱心 - 回到上一块碎片</small>",
"Survived <b>#</b> · <b>#</b> pieces · <b>#</b> hearts mended":"存活 <b>#</b> · <b>#</b>块碎片 · 修好<b>#</b>颗心",
"Survived <b>#</b> · <b>#</b> pieces · <b>#</b> heart mended":"存活 <b>#</b> · <b>#</b>块碎片 · 修好<b>#</b>颗心",
"Survived <b>#</b> · <b>#</b> pieces · <b>#</b> hearts mended · lap <b>#</b>":"存活 <b>#</b> · <b>#</b>块碎片 · 修好<b>#</b>颗心 · 第<b>#</b>圈",
"Survived <b>#</b> · <b>#</b> pieces · <b>#</b> heart mended · lap <b>#</b>":"存活 <b>#</b> · <b>#</b>块碎片 · 修好<b>#</b>颗心 · 第<b>#</b>圈",
"Your best counts on the <b>Level # Part # ∞</b> scoreboard.":"你的最佳成绩会计入<b>第#关 第#部分 ∞</b>排行榜。",
