"Score <b>#</b> · # of # planets · # meteors bounced (# on the beat)":"分数 <b>#</b> · 星球 #/# · 弹开#颗流星（#颗踩准节拍）",
"From the Earth to Planet Javeda. <b>What a journey.</b><br>Part #: meteor showers and asteroids.":"从地球到Javeda星球。<b>好一段旅程。</b><br>第#部分：流星雨和小行星。",
"From the Earth to Planet Javeda. <b>What a journey.</b><br>Part #: the meteors hunt you in flight too.":"从地球到Javeda星球。<b>好一段旅程。</b><br>第#部分：飞行途中流星也会追着你。",
