"Swing to the side the meteor comes from - early. <b>Go again.</b>":"转向流星飞来的那一侧 - 要提早。<b>再来一次。</b>",
"Let go when the dotted line points at the next planet. <b>Go again.</b>":"虚线对准下一颗星球时松手。<b>再来一次。</b>",
"PLANET SAVED<small>+# · now launch!</small>":"星球守住了<small>+# · 发射！</small>",
"<b>ENDLESS:</b> the song never ends and neither do the planets. Faster, busier, narrower - till the hearts run out. A heart back every # bars.":"<b>无尽模式：</b>歌曲永不结束，星球也没有尽头。更快、更忙、更窄 - 直到爱心用完。每#小节回复一颗爱心。",
"<b>#</b> survived · <b>#</b> planets reached · # meteors bounced (# on the beat)":"存活<b>#</b> · 抵达<b>#</b>颗星球 · 弹开#颗流星（#颗踩准节拍）",
"<b>#</b> survived · <b>#</b> planets reached · # meteors bounced":"存活<b>#</b> · 抵达<b>#</b>颗星球 · 弹开#颗流星",
"<b>#</b> survived · <b>#</b> planets reached · lap # · # meteors bounced (# on the beat)":"存活<b>#</b> · 抵达<b>#</b>颗星球 · 第#圈 · 弹开#颗流星（#颗踩准节拍）",
"<b>#</b> survived · <b>#</b> planets reached · lap # · # meteors bounced":"存活<b>#</b> · 抵达<b>#</b>颗星球 · 第#圈 · 弹开#颗流星",
"<b>REMIX:</b> all three parts in one endless trip. Each planet takes the next part's rules - Journey, Meteor Shower, The Long Way Home - and every lap is harder. +# and a heart back per lap.":"<b>混音模式：</b>三个部分串成一趟无尽旅程。每颗星球采用下一部分的规则 - Journey、Meteor Shower、The Long Way Home - 每一圈都更难。每圈+#并回复一颗爱心。",
