"Score <b>#</b> · # metres · <b>#</b> heart left · then the sky opened.":"分数 <b>#</b> · #米 · 剩<b>#</b>颗爱心 · 然后天空打开了。",
"Score <b>#</b> · # metres · <b>not a heart left</b> · then the sky opened.":"分数 <b>#</b> · #米 · <b>一颗爱心都不剩</b> · 然后天空打开了。",
"He is on foot now, on a planet that isn't his. <b>That is the album.</b>":"现在他徒步走在一颗不属于他的星球上。<b>这就是这张专辑。</b>",
"No finish line. The road goes on, faster and meaner, till the hearts run out. <b id=\"hn\"># hearts</b> · one back every # bars. Every metre is a point.":"没有终点线。道路越来越快、越来越险，直到爱心用完。<b id=\"hn\">#颗爱心</b> · 每#小节回复一颗。每一米都是一积分。",
