"Out at <b>#</b> metres · before the first checkpoint":"在<b>#</b>米处出局 · 还没到第一个检查点",
"The blue sky and the islands from the cover. A gold frame stands in the sea; Jo's saucer carries the pieces down in its beam - island chunks, gold, sky, cloud. Fill a row and it bursts gold. <b>Endless:</b> the pieces never stop - quicker every # bars, a heart back every #.":"封面上的蓝天和岛屿。海中立着一个金色框架；Jo的飞碟用光束把方块运下来 - 岛屿碎块、金块、天空、云朵。填满一行，它就会迸发金光。<b>无尽模式：</b>方块永不停止 - 每#小节变快一次，每#小节回复一颗爱心。",
