"Survived <b>#</b> · # lights · # waves jumped":"存活 <b>#</b> · 光点#个 · 跳过#道浪",
"Survived <b>#</b> · lap # · died in Island Hopper":"存活 <b>#</b> · 第#圈 · 倒在 Island Hopper",
