"<b>#</b> up in the sky · # code cracked · # tries":"高空中<b>#</b> · 破解#组 · 尝试#次",
"Every knot undone.<br>Part #, <b>Bird Code</b>, is open.":"所有结都解开了。<br>第#部分 <b>Bird Code</b> 已开放。",
"Every code cracked.<br>Level # cleared: <b>Untangle ∞</b>, <b>Bird Code ∞</b> and the <b>Remix ∞</b> are open in the gold Endless list.":"所有密码都破解了。<br>第#关已通关：<b>Untangle ∞</b>、<b>Bird Code ∞</b> 和<b>混音模式 ∞</b>已在金色无尽模式列表中开放。",
"Drag the birds until no strings cross - the red strings are the ones crossing, a red X shows where. <b>Go again.</b>":"拖动小鸟直到没有线交叉 - 红线就是交叉的线，红色 X 标出交叉点。<b>再来一次。</b>",
"Tap birds at the front to fill the wire. Gold bead: right bird, right spot. Blue bead: right bird, wrong spot. <b>Go again.</b>":"点击前面的鸟填满电线。金珠：鸟对，位置对。蓝珠：鸟对，位置错。<b>再来一次。</b>",
"Gold bead: right bird, right spot. Blue bead: right bird, wrong spot. No bead: that bird isn't hiding. <b>Go again.</b>":"金珠：鸟对，位置对。蓝珠：鸟对，位置错。没珠子：那只鸟没藏。<b>再来一次。</b>",
"A PAIR ON THE BEAT<small>+#</small>":"踩拍配对！<small>+#</small>",
"A PAIR<small>+#</small>":"配对！<small>+#</small>",
"BED CLEARED<small>+# · a bigger one</small>":"床面清空<small>+# · 下一张更大</small>",
"SNAP!<small>+# · both piles</small>":"SNAP!<small>+# · 两堆都归你</small>",
"SNAP! ON THE BEAT<small>+# · both piles</small>":"踩拍 SNAP!<small>+# · 两堆都归你</small>",
"The two rooms from the cover, split on the diagonal - hers pink, his purple; her reading with the long red hair, him on his phone in the headphones - and Jo's saucer. <b>Part # · Love Cards:</b> the cards face down on her bed. <b>Endless:</b> it never stops - harder every # bars, a heart back every #.":"封面上的两个房间，沿对角线分开 - 她的粉色，他的紫色；留着红色长发的她在看书，戴着耳机的他在玩手机 - 还有 Jo 的飞碟。<b>第#部分 · Love Cards：</b>她床上背面朝上的卡牌。<b>无尽模式：</b>永不停止 - 每#小节变难一次，每#小节回一颗爱心。",
"The two rooms from the cover, split on the diagonal - hers pink, his purple; her reading with the long red hair, him on his phone in the headphones - and Jo's saucer. <b>Part # · Snap:</b> her pile and his on the floor between them. <b>Endless:</b> it never stops - harder every # bars, a heart back every #.":"封面上的两个房间，沿对角线分开 - 她的粉色，他的紫色；留着红色长发的她在看书，戴着耳机的他在玩手机 - 还有 Jo 的飞碟。<b>第#部分 · Snap：</b>两人之间地板上她的牌堆和他的牌堆。<b>无尽模式：</b>永不停止 - 每#小节变难一次，每#小节回一颗爱心。",
"Score <b>#</b> · # pairs · # beds cleared":"分数 <b>#</b> · 配对#组 · 清空#张床",
"Score <b>#</b> · # pairs · # beds cleared · # on the beat":"分数 <b>#</b> · 配对#组 · 清空#张床 · 踩准节拍#次",
"<b>#</b> in their rooms · # pairs · # beds cleared":"房间里<b>#</b> · 配对#组 · 清空#张床",
"<b>#</b> in their rooms · # pairs · # beds cleared · # on the beat":"房间里<b>#</b> · 配对#组 · 清空#张床 · 踩准节拍#次",
"Score <b>#</b> · # snaps of # cards":"分数 <b>#</b> · SNAP #次（共#张牌）",
"<b>#</b> in their rooms · # snaps of # cards":"房间里<b>#</b> · SNAP #次（共#张牌）",
"Every pair found.<br>Part #, <b>Snap</b>, is open.":"所有配对都找到了。<br>第#部分 <b>Snap</b> 已开放。",
"Snap. Blind love.<br>Level # cleared: <b>Love Cards ∞</b>, <b>Snap ∞</b> and the <b>Remix ∞</b> are open in the gold Endless list.":"Snap。盲目的爱。<br>第#关已通关：<b>Love Cards ∞</b>、<b>Snap ∞</b> 和<b>混音模式 ∞</b>已在金色无尽模式列表中开放。",
"Turn two cards: the same picture is a pair. Remember where the others were - and clear the bed before the time's up. <b>Go again.</b>":"翻两张牌：图案相同就是一对。记住其他牌的位置 - 在时间到之前清空床面。<b>再来一次。</b>",
"When both piles show the same picture, tap - SNAP. A heart and a broken heart aren't the same. <b>Go again.</b>":"两堆出现相同图案时点击 - SNAP。爱心和破碎的心可不一样。<b>再来一次。</b>",
"Only snap when both piles show the same picture. A heart and a broken heart aren't the same, nor the sun and the moon. <b>Go again.</b>":"只有两堆图案相同时才 SNAP。爱心和破碎的心不一样，太阳和月亮也不一样。<b>再来一次。</b>",
"PAD MEMORY<small>watch the pads - then play them back</small>":"PAD MEMORY<small>看好鼓垫 - 然后照着敲一遍</small>",
"WATCH<small>watch the pads light up</small>":"看好<small>看鼓垫亮起</small>",
"NICE<small>+# · one more pad</small>":"漂亮<small>+# · 再加一个鼓垫</small>",
"# IN A ROW<small>+# · one more pad</small>":"#连击<small>+# · 再加一个鼓垫</small>",
"FULL PATTERN<small>+# · a fresh one</small>":"序列完成<small>+# · 换一组新的</small>",
"WATCH · QUICK<small>double points</small>":"看好 · 快速<small>双倍积分</small>",
"Jo's studio at night from the cover - the big speakers, the screen with the crowd, the skull on the desk. On the desk the drum machine: # pads lit from under, each its own note, and Jo's saucer hovering over them. <b>Endless:</b> the patterns never stop - less time every # bars, a heart back every #.":"封面里夜晚的 Jo 的录音室 - 大音箱、显示着人群的屏幕、桌上的骷髅头。桌上是鼓机：#个从底下亮起的鼓垫，每个一个音，Jo 的飞碟悬在上面。<b>无尽模式：</b>序列永不停止 - 每#小节时间变短，每#小节回一颗爱心。",
"Up all night and it's all still there.<br>Level # cleared: <b>Pad Memory ∞</b> is open in the gold Endless list.":"熬了一整夜，一切都还在。<br>第#关已通关：<b>Pad Memory ∞</b> 已在金色无尽模式列表中开放。",
"Play the pattern back before the time runs out - one pad a beat is plenty. <b>Go again.</b>":"在时间用完前把序列敲回来 - 一拍一个鼓垫就够了。<b>再来一次。</b>",
"Watch the order the pads light up in, then play it back the same way - say the colours to yourself. <b>Go again.</b>":"看清鼓垫亮起的顺序，再照同样顺序敲回来 - 在心里默念颜色。<b>再来一次。</b>",
