"Stay Lit<small>REMIX · LAP # · PART #</small>":"Stay Lit<small>混音模式 · 第#圈 · 第#部分</small>",
"Your best counts on the <b>Level # Remix</b> scoreboard. <b>Go again.</b>":"你的最佳成绩会计入<b>第#关 混音模式</b>排行榜。<b>再来一次。</b>",
"Deep space from the cover - the rainbow across it, the big gold moon, the two kids in the red flying car - and Jo's saucer. <b>Part # · Planet Match:</b> little planets in the rainbow's colours. <b>Endless:</b> it never stops - harder every # bars, a heart back every #.":"封面里的深空 - 横跨其中的彩虹、巨大的金色月亮、红色飞车里的两个孩子 - 还有Jo的飞碟。<b>第#部分 · Planet Match：</b>彩虹颜色的小行星。<b>无尽模式：</b>永不停止 - 每#小节更难，每#小节恢复一颗爱心。",
"Deep space from the cover - the rainbow across it, the big gold moon, the two kids in the red flying car - and Jo's saucer. <b>Part # · Rainbow Sort:</b> glass tubes, the planets mixed up in them. <b>Endless:</b> it never stops - harder every # bars, a heart back every #.":"封面里的深空 - 横跨其中的彩虹、巨大的金色月亮、红色飞车里的两个孩子 - 还有Jo的飞碟。<b>第#部分 · Rainbow Sort：</b>玻璃管里混着各色行星。<b>无尽模式：</b>永不停止 - 每#小节更难，每#小节恢复一颗爱心。",
"Deep space from the cover - the rainbow across it, the big gold moon, the two kids in the red flying car - and Jo's saucer. <b>Part # · Star Peaks:</b> three peaks of cards in front of the rainbow. <b>Endless:</b> it never stops - harder every # bars, a heart back every #.":"封面里的深空 - 横跨其中的彩虹、巨大的金色月亮、红色飞车里的两个孩子 - 还有Jo的飞碟。<b>第#部分 · Star Peaks：</b>彩虹前的三座卡牌山峰。<b>无尽模式：</b>永不停止 - 每#小节更难，每#小节恢复一颗爱心。",
