"<b>#</b> in space · # cards played · # peaks cleared · the longest streak #":"太空中<b>#</b> · 出牌#张 · 清空#座山峰 · 最长连击#",
"Planets everywhere.<br>Part #, <b>Rainbow Sort</b>, is open.":"满天行星。<br>第#部分<b>Rainbow Sort</b>已开放。",
"Every colour in its place.<br>Part #, <b>Star Peaks</b>, is open.":"每种颜色各归其位。<br>第#部分<b>Star Peaks</b>已开放。",
"Out of this world.<br>Level # cleared: <b>Planet Match ∞</b>, <b>Rainbow Sort ∞</b>, <b>Star Peaks ∞</b> and the <b>Remix ∞</b> are open in the gold Endless list.":"宇宙级精彩。<br>第#关通关：<b>Planet Match ∞</b>、<b>Rainbow Sort ∞</b>、<b>Star Peaks ∞</b>和<b>混音模式 ∞</b>已在金色无尽模式列表中开放。",
"Swap two planets side by side so three or more of a colour line up - and reach the stage's score before the time's up. <b>Go again.</b>":"交换相邻的两颗行星，让三颗或更多同色连成一线 - 在时间结束前达到本阶段的分数。<b>再来一次。</b>",
"Lift the top planet of a tube and drop it on the same colour or into an empty tube - one colour to a tube. <b>Go again.</b>":"拿起管子最上面的行星，放到同色行星上或空管里 - 一管一种颜色。<b>再来一次。</b>",
"Tap a free card one higher or one lower than the pile's top card. Stuck? Tap the deck. <b>Go again.</b>":"点击一张比牌堆顶牌大一或小一的可用卡牌。卡住了？点牌库。<b>再来一次。</b>",
"ZIRKA<small>somebody</small>":"ZIRKA<small>somebody</small>",
